codeExamples.code:
-- PostgreSQL / MySQL / SQLite
SELECT name, score FROM players ORDER BY score DESC LIMIT 10;

-- SQL Server (TOP)
SELECT TOP 10 name, score FROM players ORDER BY score DESC;

-- ANSI SQL:2008 standard (SQL Server 2012+, Oracle 12c+, PostgreSQL)
SELECT name, score FROM players
ORDER BY score DESC
OFFSET 0 ROWS FETCH FIRST 10 ROWS ONLY;

-- Include tied rows at the boundary (WITH TIES)
SELECT name, score FROM players
ORDER BY score DESC
FETCH FIRST 10 ROWS WITH TIES;
